history.rule_text:
{
 "title": "Suspicious File Download via Bitsadmin",
 "description": "Detects usage of bitsadmin to download a file with a suspicious extension, indicative of malicious file transfer.",
 "tags": [
  "attack.persistence",
  "attack.execution",
  "attack.stealth",
  "attack.t1197",
  "attack.s0190",
  "attack.t1036.003",
  "attack.command-and-control",
  "attack.t1105"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_img",
   "fields": [
    {
     "field": "Image",
     "modifier": "contains",
     "values": [
      "bitsadmin.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_cmd",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "bitsadmin"
     ]
    }
   ]
  },
  {
   "name": "selection_transfer",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/transfer"
     ]
    }
   ]
  },
  {
   "name": "selection_susp_ext",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "re",
     "values": [
      "(?i)\\.(exe|dll|bat|cmd|ps1|vbs|js|wsf|scr|hta|msi|zip)(\\s|$)"
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "selection_img and selection_cmd and selection_transfer and selection_susp_ext",
 "falsepositives": [
  "Legitimate administrative use of bitsadmin to download trusted files with suspicious extensions"
 ],
 "level": "high"
}

{
 "title": "Hashcat Password Cracker Execution",
 "description": "Detects execution of hashcat.exe with a SAM file extracted from the Windows registry, indicative of credential\n  access via password cracking.",
 "tags": [
  "attack.credential-access",
  "attack.t1110.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_hashcat_image",
   "fields": [
    {
     "field": "Image|endswith",
     "modifier": "endswith",
     "values": [
      "\\\\hashcat.exe"
     ]
    },
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      ".sam"
     ]
    }
   ]
  },
  {
   "name": "selection_hashcat_cmdline",
   "fields": [
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "hashcat.exe"
     ]
    },
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      ".sam"
     ]
    }
   ]
  }
 ],
 "condition": "(selection_hashcat_image) or (selection_hashcat_cmdline)",
 "falsepositives": [
  "Unknown"
 ],
 "level": "high"
}

{
 "title": "Chromium Based Browser Executed in Headless Mode with dump-dom",
 "description": "Detects execution of Chromium-based browsers (Chrome, Edge) launched in headless mode using the --dump-dom switch, which can be abused to download files.",
 "tags": [
  "attack.command_and_control",
  "attack.stealth",
  "attack.t1105",
  "attack.t1564.003"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\chrome.exe",
      "\\msedge.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "--headless"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "--dump-dom"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate automated testing or debugging scenarios where developers run Chrome/Edge headless with dump-dom."
 ],
 "level": "high"
}

