{
 "title": "PowerShell Timestomp Detection",
 "description": "Detects PowerShell commands that modify file timestamps (creation, modification, access) which is indicative of timestomping (T1070.006).",
 "tags": [
  "attack.t1070.006",
  "attack.stealth"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_powershell",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\powershell.exe",
      "\\pwsh.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_timestomp_cmd",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains|all",
     "values": []
    }
   ]
  }
 ],
 "condition": "selection_powershell and selection_timestomp_cmd",
 "falsepositives": [
  "Legitimate administrative scripts that intentionally set file timestamps for backup or deployment purposes."
 ],
 "level": "high"
}

{
 "title": "PowerShell Timestomp Detection",
 "description": "Detects PowerShell commands that modify file timestamps (creation, modification, access) which is indicative of timestomping (T1070.006).",
 "tags": [
  "attack.t1070.006",
  "attack.stealth"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_powershell",
   "fields": [
    {
     "field": "Image|endswith",
     "modifier": "endswith",
     "values": [
      "\\\\powershell.exe",
      "\\\\pwsh.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_timestomp_cmd",
   "fields": [
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "SetCreationTime",
      "SetLastWriteTime",
      "SetLastAccessTime",
      ".CreationTime",
      ".LastWriteTime",
      ".LastAccessTime"
     ]
    }
   ]
  },
  {
   "name": "selection_timestomp_script",
   "fields": [
    {
     "field": "ScriptBlockText|contains",
     "modifier": "contains",
     "values": [
      "SetCreationTime",
      "SetLastWriteTime",
      "SetLastAccessTime",
      ".CreationTime",
      ".LastWriteTime",
      ".LastAccessTime"
     ]
    }
   ]
  },
  {
   "name": "selection_timestomp_dotnet_method",
   "fields": [
    {
     "field": "ScriptBlockText|re",
     "modifier": "re",
     "values": [
      "\\\\[System\\\\.IO\\\\.(?:File|Directory|FileInfo)\\\\]::Set(?:Creation|LastWrite|LastAccess)Time"
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "(selection_powershell and selection_timestomp_cmd) or selection_timestomp_script or selection_timestomp_dotnet_method",
 "falsepositives": [
  "Legitimate administrative scripts that intentionally set file timestamps for backup or deployment purposes."
 ],
 "level": "high"
}

