{
 "title": "Potential UAC Bypass via SilentCleanup Task - Windir Environment Variable Modification",
 "description": "Detects attempts to modify the %windir% environment variable to a non-default value, which is indicative of abuse of the SilentCleanup scheduled task for UAC bypass.",
 "tags": [
  "attack.privilege-escalation",
  "attack.t1548.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "windir="
     ]
    }
   ]
  },
  {
   "name": "filter_normal",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "windir=C:\\\\Windows"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "windir=%SystemRoot%"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "windir=%WINDIR%"
     ]
    }
   ]
  }
 ],
 "condition": "selection and not filter_normal",
 "falsepositives": [
  "Legitimate administrative scripts that temporarily set the windir variable for testing."
 ],
 "level": "high"
}

